import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)

    files = glob(os.path.join(src_folder, '*'))
    failed_files = []
    success = True

    for file_path in files:
        if os.path.isfile(file_path):
            file_name = os.path.basename(file_path)
            dest_file_path = os.path.join(dst_folder, file_name + '.gz')
            command = f"gzip -c '{file_path}' > '{dest_file_path}'"
            try:
                result = subprocess.run(command, shell=True)
                if result.returncode != 0:
                    success = False
                    failed_files.append(file_name)
            except Exception:
                success = False
                failed_files.append(file_name)

    message = "All files compressed and moved successfully." if success else "Some files failed to compress or move."

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

